<script setup lang="ts">
import { useCmsI18n } from '@/composables/useCmsI18n';
import { computed, nextTick, onMounted, ref } from 'vue';
import { checkPermission } from '@/utils/permission';
import { cmsApi } from '../api';
import type { Scope, AccessData, SiteRole, SiteMember, TrashedMember } from '../types';
import { useOperation } from './useOperation';
import RecycleDrawer from './RecycleDrawer.vue';
import type { RecycleSource } from './recycle';
const { t } = useCmsI18n();
const props=defineProps<{scope:Scope;can:(code:string)=>boolean;isSuper:boolean}>();
const emit=defineEmits<{updated:[]}>();const {busy,error,run}=useOperation();
const data=ref<AccessData>(),candidates=ref<SiteMember[]>([]),roleDialog=ref(false),memberDialog=ref(false),roleTree=ref<{getCheckedKeys:()=>string[];setCheckedKeys:(keys:string[])=>void}>();
const roleForm=ref<{id?:string;code:string;name:string;status:number}>({code:'',name:'',status:1}),adminId=ref(''),roleIds=ref<string[]>([]);
const tree=computed(()=>Object.entries(data.value?.catalog||{}).map(([group,item])=>({code:`group:${group}`,label:item.name,children:Object.entries(item.actions).map(([action,label])=>{const code=`cms:${group}:${action}`;return {code,label,disabled:!props.isSuper&&!props.can(code)};})})));
const labels=computed(()=>Object.fromEntries(tree.value.flatMap(g=>g.children.map(c=>[c.code,c.label]))));
const selectedMember=computed(()=>candidates.value.find(m=>m.id===adminId.value)||data.value?.members.find(m=>m.id===adminId.value));
const selectedOperations=computed(()=>[...new Set((data.value?.roles||[]).filter(r=>roleIds.value.includes(r.id)).flatMap(r=>r.permissions))]);
const missingHost=computed(()=>selectedOperations.value.filter(code=>!checkPermission(selectedMember.value?.host_permissions,data.value?.ceilings[code]||[],'all')));
const effectivePreview=computed(()=>selectedOperations.value.filter(c=>!missingHost.value.includes(c)));
function mutableRole(role:SiteRole){return props.isSuper||role.permissions.every(props.can)&&!(data.value?.members||[]).some(m=>m.role_ids.includes(role.id)&&!m.manageable);}
async function load(){await run(async()=>{data.value=await cmsApi.access(props.scope.site_id);});}
async function openRole(role?:SiteRole){
 if(!props.can('cms:access:roles')||role&&!mutableRole(role))return;
 roleForm.value=role?{id:role.id,code:role.code,name:role.name,status:Number(role.status)}:{code:'',name:'',status:1};roleDialog.value=true;await nextTick();roleTree.value?.setCheckedKeys(role?.permissions||[]);
}
async function saveRole(){if(!props.can('cms:access:roles'))return;await run(async()=>{const permissions=(roleTree.value?.getCheckedKeys()||[]).filter(c=>!!labels.value[c]);await cmsApi.saveRole({...roleForm.value,site_id:props.scope.site_id,permissions});roleDialog.value=false;emit('updated');await load();});}
async function openMember(member?:SiteMember){
 if(!props.can('cms:access:members')||member&&!member.manageable)return;
 adminId.value=member?.id||'';roleIds.value=[...(member?.role_ids||[])];memberDialog.value=true;
 await run(async()=>{candidates.value=await cmsApi.candidates(props.scope.site_id);});
}
async function saveMember(){if(!props.can('cms:access:members')||!adminId.value)return;await run(async()=>{await cmsApi.assignRoles({site_id:props.scope.site_id,admin_id:adminId.value,role_ids:roleIds.value});memberDialog.value=false;emit('updated');await load();});}
async function remove(member:SiteMember){if(!props.can('cms:access:members')||!member.manageable)return;await run(async()=>{await cmsApi.removeMember({site_id:props.scope.site_id,admin_id:member.id});emit('updated');await load();});}
const recycleOpen=ref(false);
/** 回收站：被移除的成员身份，恢复时带回一起移除的角色；不在可管理范围内的账号只显示不可操作。 */
const recycleSources=computed<RecycleSource<TrashedMember>[]>(()=>[{key:'members',label:t('cms.recycle.members'),canView:props.can('cms:access:recycle'),canRestore:props.can('cms:access:restore'),canDestroy:props.can('cms:access:destroy'),
  load:async()=>{const rows=await cmsApi.trashedMembers(props.scope.site_id);return {rows,total:rows.length,pageSize:Math.max(rows.length,1)};},
  title:row=>row.real_name?`${row.real_name} (${row.username})`:row.username||row.admin_id,meta:row=>row.roles.length?t('cms.recycle.memberMeta',{roles:row.roles.map(role=>role.name).join('、')}):t('cms.labels.noRolesAssigned'),
  actionable:row=>row.manageable,
  restore:ids=>cmsApi.restoreMembers({site_id:props.scope.site_id,ids}),destroy:ids=>cmsApi.destroyMembers({site_id:props.scope.site_id,ids}),
  destroyBody:row=>t('cms.recycle.destroyMemberBody',{name:row.real_name||row.username})}]);
async function recycled(){emit('updated');await load();}
onMounted(load);
</script>
<template><div v-loading="busy" class="cms-access">
 <el-alert v-if="error" :title="error" type="error" :closable="false" />
 <el-alert :title="t('cms.labels.effectivePermissionsSystemRolePermissionsEnabledSiteRolePermissions')" type="info" :closable="false" />
 <div class="section-heading"><h3>{{ t('cms.labels.siteRoles2') }}</h3><el-button v-if="can('cms:access:roles')" type="primary" @click="openRole()">{{ t('cms.labels.newRole') }}</el-button></div>
 <el-table :data="data?.roles||[]"><el-table-column prop="name" :label="t('cms.labels.role')" min-width="140" /><el-table-column prop="code" :label="t('cms.labels.code')" min-width="150" /><el-table-column :label="t('cms.labels.permissions')" min-width="110"><template #default="{row}">{{ t('cms.labels.operationCount', { count: row.permissions.length }, row.permissions.length) }}</template></el-table-column><el-table-column :label="t('cms.labels.status')" min-width="90"><template #default="{row}"><el-tag :type="Number(row.status)?'success':'info'">{{ Number(row.status)?t('cms.labels.enabled'):t('cms.labels.disabled2') }}</el-tag></template></el-table-column><el-table-column :label="t('cms.labels.actions')" min-width="180"><template #default="{row}"><el-button v-if="can('cms:access:roles')&&mutableRole(row as SiteRole)" link type="primary" @click="openRole(row as SiteRole)">{{ t('cms.labels.editRolePermissions') }}</el-button><span v-else class="muted">{{ can('cms:access:roles')?t('cms.labels.outsideYourManagementScope'):t('cms.labels.readOnly') }}</span></template></el-table-column></el-table>
 <div class="section-heading"><h3>{{ t('cms.labels.siteMembers') }}</h3><div><el-button v-if="can('cms:access:recycle')" data-testid="open-recycle" @click="recycleOpen=true">{{ t('cms.recycle.open') }}</el-button><el-button v-if="can('cms:access:members')" type="primary" @click="openMember()">{{ t('cms.labels.addMember') }}</el-button></div></div>
 <el-table :data="data?.members||[]"><el-table-column prop="username" :label="t('cms.labels.account')" min-width="130" /><el-table-column prop="real_name" :label="t('cms.labels.name')" min-width="120" /><el-table-column :label="t('cms.labels.siteRoles')" min-width="220"><template #default="{row}"><el-tag v-for="id in row.role_ids" :key="id" class="role-tag">{{ data?.roles.find(r=>r.id===id)?.name||id }}</el-tag><span v-if="!row.role_ids.length" class="muted">{{ t('cms.labels.noRolesAssigned') }}</span></template></el-table-column><el-table-column :label="t('cms.labels.effectivePermissions')" min-width="110"><template #default="{row}">{{ t('cms.labels.operationCount', { count: row.effective.length }, row.effective.length) }}</template></el-table-column><el-table-column :label="t('cms.labels.actions')" min-width="180"><template #default="{row}"><template v-if="can('cms:access:members')&&row.manageable"><el-button link type="primary" @click="openMember(row as SiteMember)">{{ t('cms.labels.assignRoles') }}</el-button><el-popconfirm :title="t('cms.labels.revokeThisMemberSAccessToThisSite')" @confirm="remove(row as SiteMember)"><template #reference><el-button link type="danger">{{ t('cms.labels.revokeMembership') }}</el-button></template></el-popconfirm></template><span v-else class="muted">{{ t('cms.labels.youCannotManageThisAccount') }}</span></template></el-table-column></el-table>
 <el-dialog v-model="roleDialog" :title="t('cms.labels.siteRolesAndPermissions')" width="min(760px,94vw)" :close-on-click-modal="false"><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-form label-position="top"><el-form-item :label="t('cms.labels.roleCode')" required><el-input v-model="roleForm.code" :disabled="!!roleForm.id" :placeholder="t('cms.labels.eGContentEditor')" /></el-form-item><el-form-item :label="t('cms.labels.roleName')" required><el-input v-model="roleForm.name" /></el-form-item><el-form-item :label="t('cms.labels.enableRole')"><el-switch v-model="roleForm.status" :active-value="1" :inactive-value="0" /></el-form-item><el-alert :title="t('cms.labels.selectMenusAndButtonsIndividuallyDisabledActionsExceedYour')" :closable="false" /><el-tree ref="roleTree" :data="tree" node-key="code" show-checkbox default-expand-all :props="{label:'label',children:'children',disabled:'disabled'}" class="permission-tree" /></el-form><template #footer><el-button @click="roleDialog=false">{{ t('cms.labels.cancel') }}</el-button><el-button v-if="can('cms:access:roles')" type="primary" :loading="busy" @click="saveRole">{{ t('cms.labels.saveRolePermissions') }}</el-button></template></el-dialog>
 <el-dialog v-model="memberDialog" :title="t('cms.labels.assignSiteMemberRoles')" width="min(760px,94vw)" :close-on-click-modal="false"><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-form label-position="top"><el-form-item :label="t('cms.labels.administratorAccount')" required><el-select v-model="adminId" filterable @change="roleIds=[]"><el-option v-for="member in candidates" :key="member.id" :value="member.id" :label="`${member.real_name||member.username} (${member.username})`" /></el-select></el-form-item><el-form-item :label="t('cms.labels.siteRoles')"><el-checkbox-group v-model="roleIds"><el-checkbox v-for="role in data?.roles||[]" :key="role.id" :value="role.id" :disabled="!Number(role.status)||!isSuper&&!role.permissions.every(can)">{{ role.name }}{{ !Number(role.status)?t('cms.labels.disabled'):'' }}</el-checkbox></el-checkbox-group></el-form-item></el-form><template v-if="adminId"><h4>{{ t('cms.labels.estimatedPermissionsCount', { count: effectivePreview.length }) }}</h4><div class="preview-tags"><el-tag v-for="code in effectivePreview" :key="code" type="success">{{ labels[code] }}</el-tag></div><el-alert v-if="missingHost.length" :title="t('cms.labels.theseActionsAreGrantedBySiteRolesButThis')" type="warning" :closable="false" /><div class="preview-tags"><el-tag v-for="code in missingHost" :key="code" type="warning">{{ labels[code] }} · {{ data?.ceilings[code]?.join(', ') }}</el-tag></div></template><template #footer><el-button @click="memberDialog=false">{{ t('cms.labels.cancel') }}</el-button><el-button v-if="can('cms:access:members')" type="primary" :loading="busy" :disabled="!adminId" @click="saveMember">{{ t('cms.labels.saveMemberRoles') }}</el-button></template></el-dialog>
 <RecycleDrawer v-model="recycleOpen" :sources="recycleSources" @changed="recycled" />
</div></template>
<style scoped>.section-heading{display:flex;align-items:center;justify-content:space-between;margin:20px 0 12px}.section-heading h3{margin:0;font-size:15px}.role-tag{margin:2px 6px 2px 0}.muted{color:var(--el-text-color-secondary);font-size:12px}.permission-tree{margin:16px 0;max-height:48vh;overflow:auto}.preview-tags{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.cms-access :deep(.el-checkbox-group){display:flex;gap:8px;flex-wrap:wrap}</style>
